def folder(x): return (M12 if x.number<=184 else M13)/x.directory
def hierarchy(x):
    if x.number<=184: return 'Phase 5: Modeling, Semantics and Analytical Product','Module 12: Semantic Layer and Metrics Engineering'
    return 'Phase 5: Modeling, Semantics and Analytical Product','Module 13: Analytical Data Product and Self-service'
def field(text,name):
    m=re.search(rf'(?m)^\*\*{re.escape(name)}\.\*\*\s*(.+)$',text)
    if not m: raise ValueError(name)
    return m.group(1).strip()
def section(text,heading):
    m=re.search(rf'(?ms)^## {re.escape(heading)}\n\n(.*?)(?=^## |\Z)',text)
    if not m: raise ValueError(heading)
    return m.group(1).strip()
def contract(x):
    note=(folder(x)/'note.md').read_text(); after=(folder(x)/'after-note.md').read_text()
    if '**Outcome.**' in note: return tuple(field(note,k) for k in ('Outcome','Đánh giá','Lab','Pitfalls','Self-study (2,4 giờ)','Done when'))
    return (field(section(note,'Mục tiêu bài học'),'Năng lực cần chứng minh'),field(section(after,'Tiêu chí hoàn thành'),'Cách đánh giá'),field(section(after,'Thực hành'),'Nhiệm vụ'),field(section(after,'Bài làm sau buổi học'),'Lỗi cần chủ động loại trừ'),field(section(after,'Bài làm sau buổi học'),'Nhiệm vụ'),field(section(note,'Mục tiêu bài học'),'Điều kiện hoàn thành'))

def frontmatter(x):
    sources='\n'.join(f'  - {s}' for s in x.sources)
    return f'''---\nnote_id: {x.note_id}\nnote_type: concept-deep-dive\nstatus: review\nlanguage: vi\ncreated: 2026-10-02\nlast_verified: 2026-10-02\neditorial_pass: humanized-v1\nprimary_question: {x.question}\nsource_ids:\n{sources}\naliases: [{x.title}]\ntags: [wiki/database-systems, semantic-layer, data-product, governance]\nreference_path: Material/DE/Reference/Library/Knowledge-Notes/PACK-DATABASE-MODELING-BOOK-01/{x.filename}\n---\n'''

def deep_note(x):
    parts=[frontmatter(x),f'# {x.title}\n\n> [!abstract] Câu hỏi trung tâm\n> {x.question}\n']
    for i,(heading,body) in enumerate(x.core,1): parts.append(f'\n## {i}. {heading}\n\n{body}\n')
    parts.append('\n## 8. Ma trận kiểm chứng từng mệnh đề\n\nMỗi mệnh đề dưới đây cần observation, fixture hoặc artifact có thể lưu. Tên công nghệ, consensus hoặc output nhìn hợp lý không tự là bằng chứng.\n')
    for i,probe in enumerate(x.probes,1):
        parts.append(f'''\n### 8.{i}. {probe}\n\n**Mệnh đề cần kiểm.** {probe}.\n\n**Cách kiểm.** {VERIFY[x.number]} Với riêng mệnh đề này, ghi input/context, expected observation, failure signal và boundary làm kết luận không còn đúng.\n\n**Bằng chứng đạt.** Lưu contract/decision version, fixture hoặc interview evidence, command/checklist output, reviewer và artifact hash. Nếu chưa thực hiện lab, trạng thái chỉ là protocol; không ghi thành kết quả đã quan sát.\n''')
    parts.append('''\n## 9. Quy trình phản biện\n\n1. Viết decision, consumer, contract và constraints trước khi chọn tool hoặc implementation.\n2. Tách source fact, curriculum synthesis và organizational choice.\n3. Dùng counterexample và changed constraint để kiểm quyết định có đảo đúng lúc.\n4. Gắn mọi approval/certification với exact version, evidence và scope.\n5. Kiểm cả valid path lẫn negative/failure path; không chỉ demo happy path.\n6. Ghi limitation của telemetry, test environment và source authority.\n7. Chưa có execution evidence thì giữ trạng thái `review`.\n\n## 10. Câu hỏi tự kiểm tra\n\n1. Decision hoặc invariant nào đang được bảo vệ?\n2. Evidence nào độc lập với implementation đang được đánh giá?\n3. Điều kiện nào làm lựa chọn hiện tại phải đảo?\n4. Ai có quyền quyết nghĩa, ai triển khai và ai giữ quy trình?\n5. Thay đổi nào ảnh hưởng consumer dù interface vẫn chạy?\n6. Failure mode nào còn chưa có automated detector?\n\n## 11. Giới hạn và điều chưa cho phép kết luận\n\n- Chưa chạy các lab, migration, workload benchmark hoặc fault-injection; note mô tả protocol và expected evidence.\n- Tài liệu sản phẩm web được kiểm ngày 2026-10-02; feature, syntax, license và integration có thể đổi.\n- Các scorecard, lifecycle gates, failure matrix và decision contract là curriculum synthesis từ nguồn đã nêu; không gán nguyên văn cho một tác giả.\n- Ví dụ tổ chức không thay discovery thực tế, threat model, cost model hoặc owner approval.\n- Note giữ trạng thái `review` cho tới khi chủ dự án duyệt semantic meaning.\n''')
    refs='\n'.join(f'{i}. [[{s}]]' for i,s in enumerate(x.source_links,1))
    coverage='\n'.join(f'| [[{s}]] | Khái niệm, cơ chế hoặc decision boundary liên quan | Đã đọc locator được ghi trong source record; không suy ngoài phạm vi |' for s in x.source_links)
    parts.append(f'''\n## Reference\n\n{refs}\n\n## Source coverage\n\n| Source slice | Nội dung sử dụng | Trạng thái |\n|---|---|---|\n{coverage}\n\n## Key takeaways\n\n- Chọn kiến trúc và data product từ decision/constraints, không từ độ mới của công nghệ.\n- Metric governance cần versioned evidence, lifecycle gates và owner có quyền rõ.\n- Failure matrix chỉ hữu dụng khi mỗi dòng có detector hoặc control kiểm được.\n- Capstone là hồ sơ bằng chứng tích hợp, không phải bộ YAML hay dashboard trình diễn.\n- Discovery phải cho phép kết luận không xây analytics product.\n''')
    return ''.join(parts)

def curriculum(x,knowledge):
    outcome,assessment,lab,pitfalls,homework,done=contract(x); phase,module=hierarchy(x)
    header=f'# {phase}\n# {module}\n# Lesson {x.number}: {x.title}'
    body=re.sub(r'^---\n.*?\n---\n','',knowledge,flags=re.S); body=re.sub(r'^# .+\n+','',body,count=1)
    note=f'{header}\n\n## Mục tiêu bài học\n\n**Năng lực cần chứng minh.** {outcome}\n\n**Điều kiện hoàn thành.** {done}\n\n{body}'
    safety='Chỉ dùng fixture, contexts và principals thử nghiệm có phiên bản. Không đổi metric production, xóa version cũ, chạy query tốn kém hoặc dùng dữ liệu nhạy cảm. Lưu input, version, artifact hashes, raw results, approvals mô phỏng và limitations.'
    questions='\n'.join(f'{i}. {q}' for i,q in enumerate(('Nêu decision hoặc invariant trung tâm.','Đưa một phản ví dụ làm lựa chọn hiện tại sai.','Phân biệt evidence độc lập với implementation output.','Nêu owner, gate và artifact cần để hoàn thành.'),1))
    after=f'{header}\n\n## Thực hành\n\n**Nhiệm vụ.** {lab}\n\n{safety}\n\n## Kiểm tra cuối bài\n\n{questions}\n\n## Tiêu chí hoàn thành\n\n**Cách đánh giá.** {assessment}\n\n**Điều kiện đạt.** {done}\n\n## Bài làm sau buổi học\n\n**Nhiệm vụ.** {homework}\n\n**Lỗi cần chủ động loại trừ.** {pitfalls}\n\n## Reference\n\n- Knowledge note: `{(PACK/x.filename).relative_to(ROOT)}`\n- Nội dung học thuật: `note.md` cùng thư mục.\n'
    return note,after

